// --- Data Filtering and Processing ---
// This code applies the filters to the retrieved Google Sheets data

const allData = $('COMPLEX GSHEET QUERY').all();
const filterConfig = $('Code - Process Get Request').first().json;

// Helper function to check if a value matches the filter
function matchesFilter(rowValue, filter) {
  if (!rowValue) rowValue = '';
  const rowValueStr = rowValue.toString().toLowerCase();
  const filterValueStr = filter.value.toLowerCase();

  switch (filter.type) {
    case 'exact':
      return rowValueStr === filterValueStr;
    case 'contains':
      return rowValueStr.includes(filterValueStr);
    default:
      return false;
  }
}

// Filter the data based on the provided filters
const filteredResults = allData.filter(item => {
  const row = item.json;

  // All filters must match (AND logic)
  return filterConfig.filters.every(filter => {
    const fieldValue = row[filter.field];
    return matchesFilter(fieldValue, filter);
  });
});

// Prepare response data
const responseData = {
  totalFound: filteredResults.length,
  filters: filterConfig.filters.map(f => ({
    field: f.field,
    type: f.type,
    value: f.value
  })),
  data: filteredResults.map(item => item.json)
};

// Return filtered results
return filteredResults.length > 0 
  ? [{ json: responseData }]
  : [{ json: { ...responseData, error: 'No matching records found' } }];

// --- Enhanced Process Get Request ---
// This code supports multiple query types: exact match, contains, and multiple field filtering

const query = $json.query || $json;

// Define valid searchable fields
const validFields = [
  'ID', 'TYPE', 'COMPANY_DOC_ID', 'COMPANY_ID', 'COMPANY_NAME', 'HASH', "SHORT_DOC_ID",
  'NAME', 'LINK', 'SOURCE_TYPE', 'SOURCE_ID', 'STATUS', 'REQUIRED_ACTION'
];

// Helper function to validate field names
function isValidField(field) {
  return validFields.includes(field.toUpperCase());
}

// Initialize filters array
const filters = [];

// Process query parameters
for (const [key, value] of Object.entries(query)) {
  if (!value || value === '') continue; // Skip empty values

  const upperKey = key.toUpperCase();

  // Handle 'contains' queries (field_contains=value)
  if (key.endsWith('_contains')) {
    const fieldName = key.replace('_contains', '').toUpperCase();
    if (isValidField(fieldName)) {
      filters.push({
        type: 'contains',
        field: fieldName,
        value: value.toString()
      });
    }
  }
  // Handle exact match queries
  else if (isValidField(upperKey)) {
    filters.push({
      type: 'exact',
      field: upperKey,
      value: value.toString()
    });
  }
}

// Validate that at least one filter was provided
if (filters.length === 0) {
  throw new Error('Validation failed: At least one valid query parameter is required. Valid fields: ' + validFields.join(', '));
}

// Return the filters configuration
return {
  json: {
    filters: filters,
    queryType: filters.length === 1 ? 'single' : 'multiple',
    totalFilters: filters.length
  }
};

const sheet_rows = $("Get ALL GSHEET").all() 
const input_items = $input.all();

if (input_items.length === 0) return [];

// Analyze input items to determine if they all share the same filter keys
const filterKeySignatures = new Map();
const inputItemsBySignature = new Map();

for (const inputItem of input_items) {
  const keys = Object.keys(inputItem.json).sort();
  const signature = keys.join(',');

  if (!inputItemsBySignature.has(signature)) {
    filterKeySignatures.set(signature, keys);
    inputItemsBySignature.set(signature, []);
  }
  inputItemsBySignature.get(signature).push(inputItem);
}

console.log(`Processing ${input_items.length} items with ${filterKeySignatures.size} unique filter signature(s)`);

// Build indexes for each unique key signature
const indexes = new Map();

for (const [signature, filterKeys] of filterKeySignatures) {
  const index = new Map();

  for (const rowItem of sheet_rows) {
    const key = filterKeys.map(k => `${rowItem.json[k]}`).join('|');

    if (!index.has(key)) {
      index.set(key, []);
    }
    index.get(key).push(rowItem.json);
  }

  indexes.set(signature, index);
  console.log(`Built index for [${filterKeys.join(', ')}]: ${index.size} unique combinations`);
}

// Lookup matches for all input items
const results = [];

for (const [signature, items] of inputItemsBySignature) {
  const filterKeys = filterKeySignatures.get(signature);
  const index = indexes.get(signature);

  for (const inputItem of items) {
    const key = filterKeys.map(k => `${inputItem.json[k]}`).join('|');
    const matches = index.get(key) || [];

    results.push({
      filter: inputItem.json,
      matches: matches,
      matchCount: matches.length
    });
  }
}

return results;

