// OPTIMIZED REQUEST PARSER
// Determines query type and prepares filter configuration
// ═══════════════════════════════════════════════════════

const input = $input.all();

// Determine query type
const isBatch = input.length > 1;
const firstItem = input[0].json;
const keys = Object.keys(firstItem);

// Check if it's a simple ID lookup
const isSimpleId = keys.length === 1 && keys[0] === 'ID';

if (isBatch) {
  // BATCH QUERY - Multiple items to find
  const allHaveSameKeys = input.every(item => {
    const itemKeys = Object.keys(item.json).sort();
    return JSON.stringify(itemKeys) === JSON.stringify(keys.sort());
  });

  if (!allHaveSameKeys) {
    throw new Error('Batch query items must have identical key structure');
  }

  return [{
    json: {
      queryType: 'BATCH',
      filterKeys: keys,
      filters: input.map(item => item.json),
      itemCount: input.length,
      useGoogleNode: false // Always use custom filter for batch
    }
  }];
}

if (isSimpleId) {
  // SIMPLE ID LOOKUP - Use native Google Sheets node (fastest)
  return [{
    json: {
      queryType: 'SIMPLE_ID',
      idValue: firstItem.ID,
      useGoogleNode: true
    }
  }];
}

// COMPLEX FILTER - Multiple conditions
return [{
  json: {
    queryType: 'COMPLEX',
    filterKeys: keys,
    filters: [firstItem],
    useGoogleNode: keys.length <= 3 // Use Google node if 3 or fewer filters
  }
}];

// ═══════════════════════════════════════════════════════
// OPTIMIZED FILTER ENGINE
// High-performance filtering for complex and batch queries
// ═══════════════════════════════════════════════════════

const allData = $('Get All Data').all();
const config = $('Parse Request').first().json;

// Performance optimization: Build lookup structures
const startTime = Date.now();

// Helper: Check if row matches ALL filter conditions
function matchesAllConditions(row, filterObj) {
  return Object.entries(filterObj).every(([key, value]) => {
    const rowValue = row[key];

    // Handle null/undefined
    if (rowValue == null) return value == null;

    // Strict equality for numbers, case-insensitive for strings
    if (typeof rowValue === 'number' || typeof value === 'number') {
      return rowValue == value; // Loose equality for number comparison
    }

    return String(rowValue).toLowerCase() === String(value).toLowerCase();
  });
}

if (config.queryType === 'BATCH') {
  // BATCH OPTIMIZATION: Create hash map for O(1) lookups
  const filterKeys = config.filterKeys;

  // Create hash keys for all filter conditions
  const filterHashes = new Set();
  config.filters.forEach(filter => {
    const hashKey = filterKeys.map(key => String(filter[key]).toLowerCase()).join('||');
    filterHashes.add(hashKey);
  });

  // Filter data using hash lookup
  const results = allData.filter(item => {
    const row = item.json;
    const rowHash = filterKeys.map(key => String(row[key] || '').toLowerCase()).join('||');
    return filterHashes.has(rowHash);
  });

  const processingTime = Date.now() - startTime;

  return [{
    json: {
      queryType: 'BATCH',
      totalFound: results.length,
      requestedItems: config.itemCount,
      processingTimeMs: processingTime,
      filters: config.filters,
      data: results.map(item => item.json)
    }
  }];
}

// COMPLEX FILTER: Match against single filter object
const filter = config.filters[0];
const results = allData.filter(item => matchesAllConditions(item.json, filter));

const processingTime = Date.now() - startTime;

return [{
  json: {
    queryType: 'COMPLEX',
    totalFound: results.length,
    processingTimeMs: processingTime,
    filters: [filter],
    data: results.map(item => item.json)
  }
}];

// ═══════════════════════════════════════════════════════
// FORMAT GOOGLE NODE RESPONSE
// Standardizes output from native Google Sheets node
// ═══════════════════════════════════════════════════════

const config = $('Parse Request').first().json;
const results = $input.all();

return [{
  json: {
    queryType: config.queryType,
    totalFound: results.length,
    processingTimeMs: 0, // Google node handles this internally
    filters: config.queryType === 'SIMPLE_ID' 
      ? [{ ID: config.idValue }] 
      : config.filters,
    data: results.map(item => item.json)
  }
}];

// Loop over input items and remove null/undefined values
for (const item of $input.all()) {
  // Remove keys with null or undefined values
  for (const key in item.json) {
    if (item.json[key] === null || item.json[key] === undefined) {
      delete item.json[key];
    }
  }
}

return $input.all();

